/* eslint-disable @typescript-eslint/no-explicit-any */
/**
 * Minimal app-level i18n.
 *
 * Used today only for the 6 ASO frame screens (welcome / quiz-zone /
 * preview / programs / home / milestone). The full app remains
 * English at runtime; locale override is driven by the constant below
 * during screenshot batches.
 *
 * To shoot a non-English ASO pack, flip `SCREENSHOT_LOCALE` to one of
 * the supported codes — the patched screens read every string from
 * `t(key, params?)`, which prefers the active locale and falls back
 * to English on miss.
 */

export type Locale =
  | 'en'
  | 'en-GB'
  | 'de-DE'
  | 'ja'
  | 'fr-FR'
  | 'ko'
  | 'es-ES'
  | 'it-IT'
  | 'nl-NL'
  | 'sv'
  | 'pt-BR';

// Empty string = use English. Flip to e.g. 'de-DE' before a locale shot.
export const SCREENSHOT_LOCALE: string = '';

export const getLocale = (): Locale => {
  const override = SCREENSHOT_LOCALE.trim();
  if (override && (STRINGS as Record<string, Dict>)[override]) return override as Locale;
  try {
    // Device locale via Intl — works in modern Hermes/Expo SDK 55+.
    // Tries exact match first ('de-DE'), then base language ('de' → first matching variant).
    const sys = Intl.DateTimeFormat().resolvedOptions().locale;
    if ((STRINGS as Record<string, Dict>)[sys]) return sys as Locale;
    const base = sys.split('-')[0];
    const found = Object.keys(STRINGS).find((l) => l === base || l.startsWith(base + '-'));
    if (found) return found as Locale;
  } catch { /* Intl unavailable — fall through */ }
  return 'en';
};

